/// Returns `true` if the operands of a comparison are of types whose `__eq__`
/// and `__ne__` methods are known to return `bool`, in which case replacing
/// `not a == b` with `a != b` (and vice versa) cannot change the behavior of
/// the expression.
fn has_boolean_equality(left: &Expr, right: &Expr) -> bool {
    matches!(
        (ResolvedPythonType::from(left), ResolvedPythonType::from(right)),
        (ResolvedPythonType::Atom(_), ResolvedPythonType::Atom(_))
    )
}

/// SIM201
pub(crate) fn negation_with_equal_op(

    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::NotEq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    // `__eq__` may return any type, so the fix is only safe if the operand
    // types are known to compare to a `bool`.
    let edit = Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    );
    diagnostic.set_fix(if has_boolean_equality(left, &comparators[0]) {
        Fix::safe_edit(edit)
    } else {
        Fix::unsafe_edit(edit)
    });
    checker.diagnostics.push(diagnostic);
}

